parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "emailBody": {
      "type": "string",
      "description": "A concise 2-3 sentence summary of the internal email. Include explicitly stated important dates, times, deadlines, decisions, and requested actions. Do not invent missing information."
    },
    "From": {
      "type": "string",
      "description": "The sender of the internal email. Use the sender information provided in the input and do not invent a sender."
    },
    "actionRequired": {
      "type": "boolean",
      "description": "True only if the email explicitly requests an action, decision, response, preparation, or follow-up. Otherwise false."
    }
  },
  "required": [
    "emailBody",
    "From",
    "actionRequired"
  ],
  "additionalProperties": false
}

parameters.text:
=Team & Operations update

From: {{ $json.output.From }}

Summary:
{{ $json.output.emailBody }}

Action required: {{ $json.output.actionRequired ? 'Yes' : 'No' }}

parameters.jsCode:
const agentOutput = $('Internal Agent').first().json.output.emailBody;
const outputText = JSON.stringify(agentOutput);
const estimatedTokens = Math.ceil(outputText.length / 4); // груба оценка: ~4 chars = 1 token

const pricePerMillion = 0.60; // примерна цена, коригирай според модела ти
const cost = (estimatedTokens / 1_000_000) * pricePerMillion;

return [{ json: { ...$json, price: cost.toFixed(6) } }];
